function downloadPDFWithjsPDF() {
  const contentElement = document.querySelector("#content");
  // set font to Helvetica to correct render on pdf
  contentElement.style.fontFamily = "Helvetica, Arial, sans-serif";
  // create a new div with the note used on pdf
  const newDiv = document.createElement("h6");
  newDiv.id = "pdfNote";
  const newContent = document.createTextNode("Please note this pdf is autogenerated from my personal cv webpage https://andre-gra.github.io/cv/ and for this reason there may be some pagination imperfections. Hoping you can still appreciate the solution.");
  newDiv.appendChild(newContent);
  // add the newly created element and its content into the DOM
  contentElement.insertAdjacentElement('afterbegin', newDiv);

  var doc = new jspdf.jsPDF({
    orientation: 'p',
    unit: 'pt',
    format: 'a4',
    putOnlyUsedFonts: true,
    compress: true
  });

  doc.html(contentElement, {
    callback: function (doc) {
      doc.setFont("Helvetica");
      doc.save("cv.pdf");
      // set original font once pdf generation is completed
      contentElement.style.fontFamily = '"Orbitron", "Helvetica Neue", Helvetica, Arial, sans-serif, serifHelvetica, Arial, sans-serif';
      // remove note from pdf
      contentElement.removeChild(newDiv);
    },
    x: 10,
    y: 10,
    margin: [20, 10, 20, 10],
    width: 595,
    windowWidth: 1024,
    autoPaging: 'text'
  });

}

document.addEventListener("DOMContentLoaded", function (event) {
  document
    .querySelector("#jsPDF")
    .addEventListener("click", downloadPDFWithjsPDF);
});